async function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok){if(r.status===401&&path!='/auth/login'){location.reload()}throw Error(data.error||'Request failed')}return data}
async function checkVersion(){const el=$('#app-version');if(!el)return;try{const v=await api('/api/version');el.textContent=`VLOADER / ${v.currentVersion}`;el.classList.toggle('update-available',v.available&&v.updateAvailable);el.classList.toggle('version-current',v.available&&!v.updateAvailable);el.title=v.available?(v.updateAvailable?`Latest GitHub release: ${v.latestVersion}`:'Up to date'):'GitHub release check unavailable'}catch{el.classList.remove('update-available','version-current');el.title='GitHub release check unavailable'}}
