function ensureAutomationSettings(){if($('#automation-form'))return;const tabs=document.querySelector('.settings-tabs'),tab=document.createElement('button');tab.className='settings-tab';tab.type='button';tab.role='tab';tab.setAttribute('aria-selected','false');tab.setAttribute('aria-controls','automation-form');tab.dataset.settingsTab='automation-form';tab.textContent='Automation';tab.onclick=()=>selectSettingsTab('automation-form');tabs.append(tab);const form=document.createElement('form');form.id='automation-form';form.className='settings-card settings-panel hidden';form.setAttribute('role','tabpanel');form.dataset.settingsPanel='automation-form';form.innerHTML='<div><span class="section-number">07</span><h2>Sonarr &amp; Radarr</h2><p>Send approved movie and series requests to the matching tool. API keys stay on the server.</p></div><div class="automation-section"><h3>Radarr · Movies</h3><label>Radarr URL<input name="RadarrURL" type="url" placeholder="https://radarr.example.com"></label><label>API key<input name="RadarrAPIKey" type="password" autocomplete="new-password" placeholder="Enter a new API key"><small data-arr-key="radarr">Leave blank to keep the saved key.</small></label><label>Root folder<input name="RadarrRootFolder" placeholder="/media/movies"></label><label>Quality profile ID<input name="RadarrQualityID" type="number" min="0" placeholder="例如 1"></label></div><div class="automation-section"><h3>Sonarr · Series</h3><label>Sonarr URL<input name="SonarrURL" type="url" placeholder="https://sonarr.example.com"></label><label>API key<input name="SonarrAPIKey" type="password" autocomplete="new-password" placeholder="Enter a new API key"><small data-arr-key="sonarr">Leave blank to keep the saved key.</small></label><label>Root folder<input name="SonarrRootFolder" placeholder="/media/series"></label><label>Quality profile ID<input name="SonarrQualityID" type="number" min="0" placeholder="例如 1"></label><label>Language profile ID<input name="SonarrLanguageID" type="number" min="0" placeholder="例如 1"></label></div><button class="primary" type="submit">Save automation settings</button><p id="automation-result" role="status"></p>';document.querySelector('[data-settings-panel="oidc-form"]').before(form);form.onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button'),data=Object.fromEntries(new FormData(e.target));b.disabled=true;data.RadarrQualityID=Number(data.RadarrQualityID||0);data.SonarrQualityID=Number(data.SonarrQualityID||0);data.SonarrLanguageID=Number(data.SonarrLanguageID||0);try{await api('/api/settings/automation',data);await settings();$('#automation-result').textContent='Automation settings saved.';toast('Automation settings saved')}catch(err){$('#automation-result').textContent=err.message}finally{b.disabled=false}}}
function populateAutomationSettings(s){ensureAutomationSettings();const f=$('#automation-form');for(const key of ['RadarrURL','RadarrRootFolder','RadarrQualityID','SonarrURL','SonarrRootFolder','SonarrQualityID','SonarrLanguageID'])f.elements[key].value=s[key]??'';f.elements.RadarrAPIKey.value='';f.elements.SonarrAPIKey.value='';f.querySelector('[data-arr-key="radarr"]').textContent=s.HasRadarrAPIKey?'Key saved. Leave blank to keep it.':'API key is required when Radarr is enabled.';f.querySelector('[data-arr-key="sonarr"]').textContent=s.HasSonarrAPIKey?'Key saved. Leave blank to keep it.':'API key is required when Sonarr is enabled.';ensureSyncAPIKeySettings(s)}
function ensureSyncAPIKeySettings(s){const f=$('#automation-form');let section=$('#sync-api-settings');if(!section){section=document.createElement('div');section.id='sync-api-settings';section.className='automation-section';section.innerHTML='<h3>External library sync</h3><p>Generate a key for a Radarr or Sonarr webhook. The key is shown only once.</p><p><code>POST '+esc(location.origin)+'/api/external/sync</code><br><small>Header: <code>X-Api-Key: your-key</code></small></p><div class="sync-key-actions"><button class="secondary" id="sync-key-generate" type="button">Generate API key</button><button class="secondary" id="sync-key-revoke" type="button">Revoke API key</button></div><div id="sync-key-output" class="note hidden"><strong>Copy this key now:</strong><br><code></code></div><p id="sync-key-result" role="status"></p>';f.querySelector('button[type="submit"]').before(section);$('#sync-key-generate').onclick=async()=>{const button=$('#sync-key-generate');button.disabled=true;try{const result=await api('/api/settings/sync-key',{});$('#sync-key-output code').textContent=result.apiKey;$('#sync-key-output').classList.remove('hidden');$('#sync-key-result').textContent='API key created. Existing keys are no longer valid.';$('#sync-key-revoke').disabled=false;toast('Sync API key created')}catch(err){$('#sync-key-result').textContent=err.message}finally{button.disabled=false}};$('#sync-key-revoke').onclick=async()=>{const button=$('#sync-key-revoke');button.disabled=true;try{await api('/api/settings/sync-key/revoke',{});$('#sync-key-output code').textContent='';$('#sync-key-output').classList.add('hidden');$('#sync-key-result').textContent='API key revoked.';toast('Sync API key revoked')}catch(err){$('#sync-key-result').textContent=err.message}finally{button.disabled=false}}}$('#sync-key-revoke').disabled=!s.HasSyncAPIKey;if(!s.HasSyncAPIKey){$('#sync-key-output code').textContent='';$('#sync-key-output').classList.add('hidden')}$('#sync-key-result').textContent=s.HasSyncAPIKey?'An API key is active. Generate a new key to replace it.':'No API key is active.'}
function ensureRequestSearch(){const form=$('#wish-form');if(!form||$('#arr-request-search'))return;const panel=document.createElement('section');panel.id='arr-request-search';panel.className='request-search';panel.innerHTML='<h3>Search for a title</h3><p>Find the exact title first. Selecting Request creates a pending request for administrator approval.</p><div class="request-search-controls"><select aria-label="Title type"><option value="Movie">Movies</option><option value="Series">Series</option></select><input type="search" minlength="2" maxlength="100" placeholder="Search title" aria-label="Search title"><button class="secondary" type="button">Search</button></div><p class="request-search-status" role="status"></p><div class="request-search-results"></div>';form.firstElementChild.after(panel);const type=panel.querySelector('select'),input=panel.querySelector('input'),button=panel.querySelector('button'),status=panel.querySelector('.request-search-status'),results=panel.querySelector('.request-search-results');const search=async()=>{const query=input.value.trim();if(query.length<2){status.textContent='Enter at least two characters.';return}button.disabled=true;status.textContent=`Searching ${type.value==='Movie'?'movies':'series'} …`;results.innerHTML='';try{const response=await api('/api/wishes/search?type='+encodeURIComponent(type.value)+'&q='+encodeURIComponent(query));const items=response.items||[];status.textContent=items.length?`${items.length} result${items.length===1?'':'s'}`:'No matching titles found.';results.innerHTML=items.map((item,index)=>`<article class="request-search-result">${item.imageUrl?`<img class="request-search-image" src="${esc(item.imageUrl)}" alt="">`:''}<div class="request-search-copy"><h4>${esc(item.title)}</h4><small>${esc(item.type)}${item.year?' · '+esc(item.year):''}</small>${item.overview?`<p>${esc(item.overview)}</p>`:''}</div><button class="primary" type="button" data-request-result="${index}">Request</button></article>`).join('');results.querySelectorAll('[data-request-result]').forEach(resultButton=>resultButton.onclick=async()=>{const item=items[Number(resultButton.dataset.requestResult)];resultButton.disabled=true;try{await api('/api/wishes',{title:item.title,type:item.type,source:item.source,externalId:item.externalId});status.textContent='Request submitted. An administrator must approve it before processing.';toast('Request submitted');await loadWishes();form.classList.add('hidden');$('#new-request').classList.remove('hidden')}catch(err){status.textContent=err.message}finally{resultButton.disabled=false}})}catch(err){status.textContent=err.message}finally{button.disabled=false}};button.onclick=search;input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();search()}}}
