function img(item,kind='Primary'){return '/api/images/'+encodeURIComponent(item.Id)+'/'+kind}
function render(){
 const all=catalog.Items||[],selectedLibrary=catalog.Libraries.find(l=>l.Id===library);
 const libraryType=(selectedLibrary?.CollectionType||'').toLowerCase(),libraryName=(selectedLibrary?.Name||'').toLowerCase();
 const isMovieLibrary=libraryType==='movies'||/movie|film/.test(libraryName),isSeriesLibrary=libraryType==='tvshows'||libraryType==='tv'||/series|serie|show/.test(libraryName);
 const allowedType=isMovieLibrary?'Movie':(isSeriesLibrary?'Series':'');
 const cutoff=Date.now()-latestUpdatesDays*24*60*60*1000;
 let items=all.filter(i=>{const created=i.DateCreated?Date.parse(i.DateCreated):NaN;const recent=Number.isFinite(created)&&created<=Date.now()&&created>=cutoff;return(!library?((i.Type==='Movie'||i.Type==='Series')&&recent):i.LibraryId===library)&&(!allowedType||i.Type===allowedType)&&i.Type!=='Episode'&&i.Type!=='Season'&&i.Type!=='Folder'&&(!type||i.Type===type)&&i.Name.toLocaleLowerCase().includes($('#search').value.toLocaleLowerCase())});
 items.sort((a,b)=>!library?(Date.parse(b.DateCreated||'')||0)-(Date.parse(a.DateCreated||'')||0):($('#sort').value==='date'||$('#sort').value==='year')?(Date.parse(b.DateCreated||'')||0)-(Date.parse(a.DateCreated||'')||0):$('#sort').value==='rating'?(b.CommunityRating||0)-(a.CommunityRating||0):a.Name.localeCompare(b.Name));
 const countSource=all.filter(i=>(!library||i.LibraryId===library)&&i.Type!=='Folder'),movieCount=countSource.filter(i=>i.Type==='Movie').length,seriesCount=countSource.filter(i=>i.Type==='Series').length,seasonCount=countSource.filter(i=>i.Type==='Season').length,episodeCount=countSource.filter(i=>i.Type==='Episode').length;
 $('#item-count').textContent=allowedType==='Movie'?`${movieCount} movie${movieCount===1?'':'s'}`:allowedType==='Series'?`${seriesCount} series${seriesCount===1?'':'s'} · ${seasonCount} season${seasonCount===1?'':'s'} · ${episodeCount} episode${episodeCount===1?'':'s'}`:`${movieCount} movie${movieCount===1?'':'s'} · ${seriesCount} series${seriesCount===1?'':'s'} · ${seasonCount} season${seasonCount===1?'':'s'} · ${episodeCount} episode${episodeCount===1?'':'s'}`;
 const syncedAt=catalog.Updated&&!catalog.Updated.startsWith('0001')?new Date(catalog.Updated):null;$('#updated').textContent=syncedAt?'Updated '+syncedAt.toLocaleString('en-GB'):'Not synced yet';for(const lastSync of [$('#last-sync'),$('#user-last-sync')])if(lastSync)lastSync.textContent=syncedAt?'Last sync: '+syncedAt.toLocaleString('en-GB'):'Last sync: —';
 $('#collection-title').textContent=selectedLibrary?.Name||'Latest updates';$('#sort').classList.toggle('hidden',!library);
 $('#grid').innerHTML=items.slice(0,limit).map(i=>`<article class="movie"><div class="poster-shell"><button class="poster" data-id="${esc(i.Id)}" aria-label="${esc(i.Name)} – Details">${i.ImageTags?.Primary?`<img loading="lazy" decoding="async" src="${img(i)}" alt="${esc(i.Name)}">`:`<span class="poster-fallback">${esc(i.Name)}</span>`}</button>${!i.IsFolder?`<a class="download-indicator download-action" href="/api/download/${encodeURIComponent(i.Id)}" download aria-label="Download ${esc(i.Name)}">Download</a>`:''}</div><div class="movie-meta"><h3>${esc(i.Name)}</h3>${i.CommunityRating?`<p class="movie-rating">★ ${i.CommunityRating.toFixed(1)}</p>`:''}<p>${i.ProductionYear||(i.PremiereDate?new Date(i.PremiereDate).getFullYear():'–')}</p><p>${esc((i.Genres||[]).slice(0,2).join(', ')||i.Type)}</p></div></article>`).join('');
 $('#empty').classList.toggle('hidden',items.length>0);$('#empty h3').textContent=all.length?'No recent titles.':'Room for your favorite movies.';$('#empty p').textContent=all.length?`No movies or series were added in the last ${latestUpdatesDays} days.`:'Connect Emby in Settings, then sync your collection.';$('#more').classList.toggle('hidden',items.length<=limit);document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>detail(b.dataset.id));document.querySelectorAll('#grid img').forEach(i=>i.onerror=()=>{const s=document.createElement('span');s.className='poster-fallback';s.textContent=i.alt;i.replaceWith(s)});
}
function renderCatalog(){catalog.Items??=[];catalog.Libraries??=[];$('#libraries').innerHTML=catalog.Libraries.slice().sort((a,b)=>a.Name.localeCompare(b.Name,undefined,{numeric:true,sensitivity:'base'})).map(l=>`<button class="nav" data-lib="${esc(l.Id)}">▤ <span>${esc(l.Name)}</span></button>`).join('');document.querySelectorAll('[data-lib]').forEach(b=>b.onclick=()=>{library=library===b.dataset.lib?'':b.dataset.lib;document.querySelectorAll('[data-lib]').forEach(x=>x.classList.toggle('active',x.dataset.lib===library));show('collection');limit=40;render()});featured=catalog.Items.find(i=>i.BackdropImageTags?.length&&!i.IsFolder)||catalog.Items.find(i=>!i.IsFolder);if(featured){$('#hero h2').textContent=featured.Name;$('#hero-copy').textContent=featured.Overview||'Explore this title in your collection.';$('#hero-action').textContent='Explore title';if(featured.BackdropImageTags?.length)$('#hero').style.backgroundImage=`url("${img(featured,'Backdrop')}")`;}render()}
function descendants(id,type){return catalog.Items.filter(i=>i.Type===type&&(i.ParentId===id||(type==='Season'&&i.SeriesId===id)||(type==='Episode'&&i.SeasonId===id)))}
function episodeRow(e){return `<div class="episode-row"><button class="episode-detail" data-id="${esc(e.Id)}">Episode ${e.IndexNumber||'?'} · ${esc(e.Name)}</button><a class="button primary episode-download download-action" href="/api/download/${encodeURIComponent(e.Id)}" download aria-label="Download episode ${e.IndexNumber||'?'}: ${esc(e.Name)}">Download</a></div>`}
function detail(id){const i=catalog.Items.find(i=>i.Id===id);if(!i)return;let body=`<div class="detail-grid"><div>${i.ImageTags?.Primary?`<img src="${img(i)}" alt="${esc(i.Name)}">`:''}</div><div><small>${esc(i.Type)}${i.ProductionYear?' / '+i.ProductionYear:''}${i.PremiereDate?' / '+new Date(i.PremiereDate).toLocaleDateString('en-GB'):''}</small><h2>${esc(i.Name)}</h2><p>${esc((i.Genres||[]).join(' · '))}${i.RunTimeTicks?' · '+Math.round(i.RunTimeTicks/600000000)+' min':''}</p><p>${esc((i.MediaStreams||[]).filter(s=>s.Type==='Video').map(s=>s.DisplayTitle||s.Codec).join(' / ')||'Video details unavailable.')}</p><p>${esc((i.MediaStreams||[]).filter(s=>s.Type==='Audio').map(s=>s.DisplayTitle||s.Codec).join(' / ')||'Audio details unavailable.')}</p><p>${esc(i.Overview||'No description available in Emby.')}</p></div></div>`;if(i.Type==='Series'){const seasons=descendants(i.Id,'Season').sort((a,b)=>(a.IndexNumber||0)-(b.IndexNumber||0));body+=`<div class="series-tree">${seasons.map(s=>`<section><button class="series-node" data-id="${esc(s.Id)}">${s.ImageTags?.Primary?`<img src="${img(s)}" alt="${esc(s.Name)}">`:''}<span><small>Season ${s.IndexNumber||s.Name}</small><strong>${esc(s.Name)}</strong></span></button><button class="button primary season-download download-action" data-season-download="${esc(s.Id)}">Download season (${descendants(s.Id,'Episode').length} episodes)</button><div class="episode-list">${descendants(s.Id,'Episode').sort((a,b)=>(a.IndexNumber||0)-(b.IndexNumber||0)).map(episodeRow).join('')||'<small>No episodes found in this season.</small>'}</div></section>`).join('')||'<p>No seasons found in this series.</p>'}</div>`}else if(i.Type==='Season'){body+=`<div class="episode-list">${descendants(i.Id,'Episode').sort((a,b)=>(a.IndexNumber||0)-(b.IndexNumber||0)).map(episodeRow).join('')}</div>`}else if(!i.IsFolder){body+=`<a class="button primary download-action" href="/api/download/${encodeURIComponent(i.Id)}">Download</a>`}else{body+='<p>Downloads are available for individual movies and episodes.</p>'}$('#detail-content').innerHTML=body;$('#detail').showModal();document.querySelectorAll('#detail [data-id]').forEach(b=>b.onclick=()=>detail(b.dataset.id));document.querySelectorAll('[data-season-download]').forEach(b=>b.onclick=()=>downloadSeason(b.dataset.seasonDownload))}
function downloadSeason(seasonId){const episodes=descendants(seasonId,'Episode').sort((a,b)=>(a.IndexNumber||0)-(b.IndexNumber||0));if(!episodes.length){toast('No episodes are available to download');return}for(const episode of episodes){const link=document.createElement('a');link.href='/api/download/'+encodeURIComponent(episode.Id);link.download='';document.body.append(link);link.click();link.remove()}toast(`Started ${episodes.length} individual episode downloads`)}
function wishCard(w){const who=wishesAdmin?` · Requested by ${esc(w.requesterName||w.requester)}`:'';const reference=w.sourceUrl?`<a class="wish-reference" href="${esc(w.sourceUrl)}" target="_blank" rel="noopener noreferrer">Open ${esc(w.source.toUpperCase())}</a>`:'';const matched=catalog.Items.find(item=>item.Id===w.itemId);const embyPoster=matched&&matched.ImageTags?.Primary?img(matched):'';const approval=wishesAdmin&&w.status==='pending'?`<div class="wish-actions"><label>Destination folder<select class="wish-root" data-option-type="${esc(w.type)}"><option value="">Loading folders …</option></select></label><label>Quality profile<select class="wish-quality" data-option-type="${esc(w.type)}"><option value="">Loading profiles …</option></select></label>${w.type==='Series'?`<label class="wish-language-wrap hidden">Language profile<select class="wish-language" data-option-type="Series"><option value="">Select language profile</option></select></label>`:''}<button class="secondary" data-wish-id="${esc(w.id)}" data-wish-status="approved">Approve</button><button class="secondary" data-wish-id="${esc(w.id)}" data-wish-status="rejected">Decline</button></div>`:'';const cancellation=w.canCancel?`<button class="secondary request-cancel" type="button" data-wish-cancel="${esc(w.id)}">Cancel request</button>`:'';const ownRemoval=!wishesAdmin&&w.canDelete?`<button class="secondary request-delete" type="button" data-wish-own-delete="${esc(w.id)}">Delete</button>`:'';const removal=wishesAdmin?`<button class="secondary request-delete" type="button" data-wish-delete="${esc(w.id)}">Delete</button>`:'';return `<article class="wish-row" data-wish-card="${esc(w.id)}"><img class="wish-poster${embyPoster?'':' hidden'}" ${embyPoster?`src="${esc(embyPoster)}"`:''} alt="${esc(w.title)}" onerror="this.classList.add('hidden')"><div class="wish-content"><h3>${esc(w.title)}</h3><p>${esc(w.type)} · ${esc(w.source.toUpperCase())}${w.externalId?' · '+esc(w.externalId):''}${who}</p>${reference}<div class="wish-metadata hidden"></div><p class="wish-status wish-${esc(w.status)}">${esc(wishStatus(w.status))}</p>${w.itemId?`<a class="button primary download-action" href="/api/download/${encodeURIComponent(w.itemId)}" download>Download</a>`:''}${cancellation}${ownRemoval}</div>${approval}${removal}</article>`}
function showWishMetadata(card, id){api('/api/wishes/'+encodeURIComponent(id)+'/metadata').then(meta=>{if(meta.posterUrl){const image=card.querySelector('.wish-poster');if(image.classList.contains('hidden')){image.src=meta.posterUrl;image.alt=meta.title;image.classList.remove('hidden')}}const details=card.querySelector('.wish-metadata');const facts=[meta.title,meta.releaseDate?meta.releaseDate.slice(0,4):'',(meta.genres||[]).join(', '),meta.rating?`★ ${meta.rating.toFixed(1)}`:'',meta.runtime?`${meta.runtime} min`:''].filter(Boolean);if(facts.length){details.textContent=facts.join(' · ');details.classList.remove('hidden')}if(meta.overview){const description=document.createElement('p');description.className='wish-overview';description.textContent=meta.overview;details.after(description)}}).catch(()=>{})}
function observeWishMetadata(){if(!metadataEnabled)return;const cards=[...document.querySelectorAll('[data-wish-card]')];if(!('IntersectionObserver'in window)){cards.slice(0,40).forEach(card=>showWishMetadata(card,card.dataset.wishCard));return}const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){observer.unobserve(entry.target);showWishMetadata(entry.target,entry.target.dataset.wishCard)}}},{rootMargin:'250px'});cards.forEach(card=>observer.observe(card))}
function wishStatus(status){return ({pending:'Waiting for admin review',approved:'Approved · waiting for library sync',rejected:'Declined',available:'Available in your library',cancelled:'Cancelled'})[status]||status}
