function formatBytes(bytes){if(!Number.isFinite(bytes)||bytes<0)return 'Unknown';if(bytes<1024)return `${bytes} B`;const units=['KB','MB','GB','TB'];let value=bytes,index=-1;do{value/=1024;index++}while(value>=1024&&index<units.length-1);return `${value.toFixed(value>=10||index===0?0:1)} ${units[index]}`}
