function renderDownloadHistory(items){const target=$('#download-history');if(!target)return;target.innerHTML=items.length?items.slice(0,10).map(download=>{const known=download.totalBytes>0,progress=known?`${formatBytes(download.loadedBytes)} / ${formatBytes(download.totalBytes)}`:formatBytes(download.loadedBytes),status=download.status==='cancelled'?'Cancelled':download.status==='completed'?'Completed':'Finished';return `<article class="download-history-entry"><div><h3>${esc(download.title)}</h3><p>${esc(download.mediaType||'Media')} · Downloaded by ${esc(download.user||'Unknown user')} · ${status}${download.loadedBytes>0?` · ${progress}`:''}</p></div><div class="download-history-actions"><small>${new Date(download.finishedAt||download.startedAt).toLocaleString('en-GB')}</small><button class="secondary history-delete" type="button" data-download-history-delete="${esc(download.id)}">Delete</button></div></article>`}).join(''):'<p class="empty-note">No download history yet.</p>'}
async function loadDownloadHistory(){const history=await api('/api/admin/download-history');renderDownloadHistory(history.items||[])}
async function loadAdminWorkspace(){const wishes=await api('/api/admin/wishes');metadataEnabled=!!wishes.metadataEnabled;const note=$('#admin-request-metadata-note');note.classList.toggle('hidden',metadataEnabled);note.textContent=metadataEnabled?'':'Configure request automation under Settings to load title details.';const previousAdmin=wishesAdmin;wishesAdmin=true;$('#admin-wishes-list').innerHTML=(wishes.items||[]).length?(wishes.items||[]).map(wishCard).join(''):'<p class="empty-note">No requests yet.</p>';wishesAdmin=previousAdmin;observeWishMetadata();await Promise.all([refreshActiveDownloads(),loadDownloadHistory()]);await populateAdminApprovalControls();document.querySelectorAll('#admin-wishes-list [data-wish-status]').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-wish-card]'),root=card.querySelector('.wish-root')?.value||'',quality=Number(card.querySelector('.wish-quality')?.value||0),language=Number(card.querySelector('.wish-language')?.value||0);if(button.dataset.wishStatus==='approved'&&(!root||!quality)){toast(!root?'Select a destination folder':'Select a quality profile');return}if(button.dataset.wishStatus==='approved'&&card.querySelector('.wish-language')?.required&&!language){toast('Select a language profile');return}button.disabled=true;try{await api('/api/wishes/'+encodeURIComponent(button.dataset.wishId),{status:button.dataset.wishStatus,rootFolderPath:root,qualityProfileId:quality,languageProfileId:language});await loadAdminWorkspace()}catch(err){toast(err.message)}finally{button.disabled=false}});document.querySelectorAll('#admin-wishes-list [data-wish-delete]').forEach(button=>button.onclick=event=>{event.stopPropagation();const dialog=$('#delete-confirm');dialog.dataset.wishDelete=button.dataset.wishDelete;dialog.dataset.adminView='true';dialog.showModal()});if(!adminPoll)adminPoll=setInterval(()=>{if(!$('#admin').classList.contains('hidden'))Promise.all([refreshActiveDownloads(),loadDownloadHistory()]).catch(()=>{})},2500)}
$('#admin-nav').onclick=()=>show('admin');
const deleteRequest=$('#delete-confirm-approve').onclick;$('#delete-confirm-approve').onclick=async()=>{const dialog=$('#delete-confirm');if(dialog.dataset.wishOwnDelete){const id=dialog.dataset.wishOwnDelete,button=$('#delete-confirm-approve');button.disabled=true;try{await api('/api/wishes/'+encodeURIComponent(id)+'/remove',{});dialog.close();delete dialog.dataset.wishOwnDelete;toast('Request deleted');await loadWishes()}catch(err){toast(err.message)}finally{button.disabled=false}return}if(dialog.dataset.adminView!=='true')return deleteRequest();const id=dialog.dataset.wishDelete;if(!id)return;const button=$('#delete-confirm-approve');button.disabled=true;try{await api('/api/wishes/'+encodeURIComponent(id)+'/delete',{});dialog.close();delete dialog.dataset.wishDelete;delete dialog.dataset.adminView;toast('Request deleted');await loadAdminWorkspace()}catch(err){toast(err.message)}finally{button.disabled=false}};

const historyDeleteDialog=$('#history-delete-confirm');document.addEventListener('click',event=>{const button=event.target.closest('[data-download-history-delete]');if(!button)return;historyDeleteDialog.dataset.entryId=button.dataset.downloadHistoryDelete;historyDeleteDialog.showModal()});historyDeleteDialog.onclick=event=>{if(event.target===historyDeleteDialog)historyDeleteDialog.close()};$('#history-delete-cancel').onclick=()=>historyDeleteDialog.close();$('#history-delete-approve').onclick=async()=>{const id=historyDeleteDialog.dataset.entryId;if(!id)return;const button=$('#history-delete-approve');button.disabled=true;try{await api('/api/admin/download-history/'+encodeURIComponent(id)+'/delete',{});historyDeleteDialog.close();delete historyDeleteDialog.dataset.entryId;await loadDownloadHistory();toast('Download history entry deleted')}catch(err){toast(err.message)}finally{button.disabled=false}};
